import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"大作文","description":"","frontmatter":{},"headers":[],"relativePath":"shenlun/dazuowen.md","filePath":"shenlun/dazuowen.md"}'),o={name:"shenlun/dazuowen.md"};function n(s,t,l,h,i,u){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="大作文" tabindex="-1">大作文 <a class="header-anchor" href="#大作文" aria-label="Permalink to &quot;大作文&quot;">​</a></h1><p>申论大作文 1000-1200 字，占分重（40分左右），是拉开差距的关键。</p><h2 id="📐-基本框架-总-→-分-→-总" tabindex="-1">📐 基本框架：总 → 分 → 总 <a class="header-anchor" href="#📐-基本框架-总-→-分-→-总" aria-label="Permalink to &quot;📐 基本框架：总 → 分 → 总&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开头（150字）  → 亮出总论点</span></span>
<span class="line"><span>分论点1（250字）→ 论证角度一</span></span>
<span class="line"><span>分论点2（250字）→ 论证角度二</span></span>
<span class="line"><span>分论点3（250字）→ 论证角度三</span></span>
<span class="line"><span>结尾（150字）  → 升华总结</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="一、开头写法" tabindex="-1">一、开头写法 <a class="header-anchor" href="#一、开头写法" aria-label="Permalink to &quot;一、开头写法&quot;">​</a></h2><h3 id="_5种高分开头" tabindex="-1">5种高分开头 <a class="header-anchor" href="#_5种高分开头" aria-label="Permalink to &quot;5种高分开头&quot;">​</a></h3><p><strong>1. 引用式开头</strong></p><blockquote><p>&quot;治国有常，而利民为本。&quot; 民之所望，政之所向。当前...</p></blockquote><p><strong>2. 时代背景式</strong></p><blockquote><p>站在&quot;十四五&quot;规划收官之年的关键节点上，...问题日益凸显...</p></blockquote><p><strong>3. 现象+转折式</strong></p><blockquote><p>近年来，...取得了长足进步。然而，...问题仍不容忽视。</p></blockquote><p><strong>4. 设问式</strong></p><blockquote><p>如何让...既能...又能...？这成为当前必须回答的时代命题。</p></blockquote><p><strong>5. 案例式</strong></p><blockquote><p>从浙江&quot;最多跑一次&quot;到北京&quot;接诉即办&quot;，各地探索表明...</p></blockquote><hr><h2 id="二、分论点论证" tabindex="-1">二、分论点论证 <a class="header-anchor" href="#二、分论点论证" aria-label="Permalink to &quot;二、分论点论证&quot;">​</a></h2><h3 id="论证结构" tabindex="-1">论证结构 <a class="header-anchor" href="#论证结构" aria-label="Permalink to &quot;论证结构&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分论点（一句话）→ 说理解释（为什么）→ 举例论证 → 回归分论点</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="论证方法" tabindex="-1">论证方法 <a class="header-anchor" href="#论证方法" aria-label="Permalink to &quot;论证方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>用法</th><th>示例</th></tr></thead><tbody><tr><td>举例论证</td><td>举具体案例</td><td>&quot;比如，某地通过...实现了...&quot;</td></tr><tr><td>正反论证</td><td>做/不做对比</td><td>&quot;如果...,那么...；反之，如果...，那么...&quot;</td></tr><tr><td>因果论证</td><td>分析因果关系</td><td>&quot;正是因为...,才导致...&quot;</td></tr><tr><td>数据论证</td><td>用数据说话</td><td>&quot;据统计，...增长了X%&quot;</td></tr><tr><td>引用论证</td><td>引政策/名言/原理</td><td>&quot;习近平总书记指出...&quot;</td></tr></tbody></table><h3 id="常见分论点角度" tabindex="-1">常见分论点角度 <a class="header-anchor" href="#常见分论点角度" aria-label="Permalink to &quot;常见分论点角度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角度</th><th>分论点模板</th></tr></thead><tbody><tr><td>主体</td><td>政府→企业→个人</td></tr><tr><td>领域</td><td>经济→社会→生态</td></tr><tr><td>环节</td><td>思想→制度→执行→监督</td></tr><tr><td>发展</td><td>过去成就→当下挑战→未来方向</td></tr><tr><td>辩证</td><td>怎么看→怎么办→怎么好</td></tr></tbody></table><hr><h2 id="三、结尾写法" tabindex="-1">三、结尾写法 <a class="header-anchor" href="#三、结尾写法" aria-label="Permalink to &quot;三、结尾写法&quot;">​</a></h2><h3 id="_3种经典结尾" tabindex="-1">3种经典结尾 <a class="header-anchor" href="#_3种经典结尾" aria-label="Permalink to &quot;3种经典结尾&quot;">​</a></h3><p><strong>1. 呼应式</strong></p><blockquote><p>开头提了&quot;民生&quot;，结尾回到&quot;民生&quot; → 形成闭环</p></blockquote><p><strong>2. 展望式</strong></p><blockquote><p>用对未来可期的描述收束全文</p></blockquote><p><strong>3. 号召式</strong></p><blockquote><p>呼吁各方行动起来</p></blockquote><h3 id="结尾高频句式" tabindex="-1">结尾高频句式 <a class="header-anchor" href="#结尾高频句式" aria-label="Permalink to &quot;结尾高频句式&quot;">​</a></h3><ul><li>&quot;道虽迩，不行不至；事虽小，不为不成。&quot;</li><li>&quot;一分部署，九分落实。&quot;</li><li>&quot;功成不必在我，功成必定有我。&quot;</li></ul><hr><h2 id="📝-素材积累" tabindex="-1">📝 素材积累 <a class="header-anchor" href="#📝-素材积累" aria-label="Permalink to &quot;📝 素材积累&quot;">​</a></h2><h3 id="名言金句" tabindex="-1">名言金句 <a class="header-anchor" href="#名言金句" aria-label="Permalink to &quot;名言金句&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>金句</th></tr></thead><tbody><tr><td>民生</td><td>民之所忧，我必念之；民之所盼，我必行之</td></tr><tr><td>奋斗</td><td>路虽远，行则将至；事虽难，做则必成</td></tr><tr><td>创新</td><td>惟创新者进，惟创新者强，惟创新者胜</td></tr><tr><td>生态</td><td>绿水青山就是金山银山</td></tr><tr><td>法治</td><td>国无常强，无常弱。奉法者强则国强</td></tr></tbody></table><h3 id="案例素材" tabindex="-1">案例素材 <a class="header-anchor" href="#案例素材" aria-label="Permalink to &quot;案例素材&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>案例</th></tr></thead><tbody><tr><td></td><td></td></tr><tr><td></td><td></td></tr></tbody></table><hr><h2 id="📝-练习记录" tabindex="-1">📝 练习记录 <a class="header-anchor" href="#📝-练习记录" aria-label="Permalink to &quot;📝 练习记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>作文题目</th><th>用时</th><th>自评</th><th>需要改进</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>`,45)])])}const c=a(o,[["render",n]]);export{b as __pageData,c as default};
